"use client";

import { useEffect, useMemo, useState } from "react";

type Provider = { id: string; name: string; platform: string; protocol: string; baseUrl: string; status: string; credentialCount: number; availableCredentials: number; modelCount: number; billingType: string; concurrencyLimit:number;rpmLimit:number;tpmLimit:number;timeoutMs:number;usedRequests30d:number;usedTokens30d:number;localCost30d:number;meteringGaps30d:number };
type HealthEvent = { id: string; level: string; eventType: string; summary: string; readAt:string|null; createdAt: string };
type Credential = { id:string;providerId:string;name:string;prefix:string;status:string;priority:number;weight:number;concurrencyLimit:number;rpmLimit:number;tpmLimit:number;lastUsedAt:string|null;lastSuccessAt:string|null;lastError:string|null;createdAt:string };
type Model = { id:string;providerId:string;upstreamModelId:string;displayName:string;publicName:string;routeId:string|null;routePriority:number;routeConcurrency:number;allowFailover:boolean;supportsChat:boolean;supportsStreaming:boolean;supportsTools:boolean;supportsVision:boolean;contextWindow:number;maxOutputTokens:number;status:string };
type PriceVersion={id:string;providerModelId:string;billingKind:string;currency:string;unit:string;inputPrice:number|null;outputPrice:number|null;cacheInputPrice:number|null;userInputPrice:number|null;userOutputPrice:number|null;effectiveAt:string;expiresAt:string|null;verifiedAt:string|null;sourceNote:string|null};
type MemberKey = {id:string;memberId:string;name:string;prefix:string;status:string;rpmLimit:number|null;tpmLimit:number|null;concurrencyLimit:number|null;lastUsedAt:string|null;createdAt:string};
type Member = {id:string;name:string;email:string|null;status:string;monthlyRequestLimit:number|null;monthlyTokenLimit:number|null;effectiveRequestLimit:number|null;effectiveTokenLimit:number|null;quotaSource:"card"|"member";quotaStatus:"active"|"expired";activeEntitlementCount:number;entitlementStartsAt:string|null;entitlementExpiresAt:string|null;rpmLimit:number;tpmLimit:number;concurrencyLimit:number;keys:MemberKey[];usedRequests:number;usedTokens:number;createdAt:string};
type MemberPolicy={id:string;memberId:string;publicModelId:string;effect:string};
type Invitation = {id:string;code:string;email:string|null;note:string|null;status:string;monthlyRequestLimit:number|null;monthlyTokenLimit:number|null;rpmLimit:number;concurrencyLimit:number;expiresAt:string;redeemedAt:string|null;memberId:string|null;createdAt:string};
type Call = {id:string;requestId:string;memberId:string|null;publicModel:string;upstreamModel:string|null;inputTokens:number;outputTokens:number;status:string;httpStatus:number|null;durationMs:number|null;createdAt:string};
type Audit = {id:string;actor:string;action:string;objectType:string;summary:string;result:string;createdAt:string};
type QuotaRule={id:string;name:string;memberId:string|null;providerId:string|null;windowSeconds:number;requestLimit:number|null;tokenLimit:number|null;enabled:boolean};
type Snapshot = { gatewayEnabled: boolean; providers: Provider[]; credentials:Credential[];models:Model[];publicModels:{id:string;name:string}[];priceVersions:PriceVersion[];members:Member[];memberPolicies:MemberPolicy[];invitations:Invitation[];quotaRules:QuotaRule[];calls:Call[];audits:Audit[];settings:Record<string,string>; stats: { providers: number; healthyProviders: number; credentials: number; models: number; members: number; callsToday: number; successRate: number; activeLeases: number }; events: HealthEvent[] };

const navigation = [
  ["overview", "概览", "⌁"], ["providers", "模型提供商", "◫"], ["models", "模型与价格", "◇"],
  ["members", "成员管理", "♙"], ["invites", "邀请管理", "✉"], ["limits", "额度与流量", "◌"],
  ["calls", "调用记录", "≋"], ["alerts", "告警中心", "△"], ["audit", "审计日志", "⌘"], ["settings", "系统设置", "⚙"],
];

const templates = [
  { name: "OpenAI 官方", platform: "OpenAI", protocol: "OpenAI", baseUrl: "https://api.openai.com/v1" },
  { name: "火山 Agent Plan · OpenAI", platform: "火山 Agent Plan", protocol: "OpenAI Compatible", baseUrl: "https://ark.cn-beijing.volces.com/api/plan/v3" },
  { name: "火山 Agent Plan · Anthropic", platform: "火山 Agent Plan", protocol: "Anthropic Compatible", baseUrl: "https://ark.cn-beijing.volces.com/api/plan" },
  { name: "火山 Coding Plan · OpenAI", platform: "火山 Coding Plan", protocol: "OpenAI Compatible", baseUrl: "https://ark.cn-beijing.volces.com/api/coding/v3" },
  { name: "火山 Coding Plan · Anthropic", platform: "火山 Coding Plan", protocol: "Anthropic Compatible", baseUrl: "https://ark.cn-beijing.volces.com/api/coding" },
  { name: "火山方舟标准 API", platform: "火山方舟", protocol: "OpenAI Compatible", baseUrl: "https://ark.cn-beijing.volces.com/api/v3" },
];

const empty: Snapshot = { gatewayEnabled: true, providers: [],credentials:[],models:[],publicModels:[],priceVersions:[],members:[],memberPolicies:[],invitations:[],quotaRules:[],calls:[],audits:[],settings:{}, stats: { providers: 0, healthyProviders: 0, credentials: 0, models: 0, members: 0, callsToday: 0, successRate: 100, activeLeases: 0 }, events: [] };

export default function Home() {
  const [active, setActive] = useState("overview");
  const [data, setData] = useState<Snapshot>(empty);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState<"provider" | "member" | "credential" | "model" | "invite" | null>(null);
  const [selectedProvider, setSelectedProvider] = useState<Provider | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState(1);
  const [notice, setNotice] = useState("");

  async function refresh() {
    try { const res = await fetch("/api/control-plane", { cache: "no-store" }); if (res.ok) setData(await res.json()); }
    finally { setLoading(false); }
  }
  useEffect(() => { refresh(); }, []);

  async function action(payload: Record<string, unknown>) {
    const res = await fetch("/api/control-plane", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) });
    const result = await res.json() as { error?: string; apiKey?: string; inviteCode?:string; message?: string };
    if (!res.ok) return setNotice(result.error || "操作失败");
    setModal(null); setNotice(result.apiKey ? `个人 API Key（仅显示一次）：${result.apiKey}` : result.inviteCode ? `邀请已创建，兑换码：${result.inviteCode}` : result.message || "保存成功"); await refresh();
  }

  const title = useMemo(() => navigation.find(n => n[0] === active)?.[1] || "概览", [active]);

  return <main className="shell">
    <aside className="sidebar">
      <div className="brand"><span className="brandmark">N</span><div><strong>New API</strong><small>CONTROL PLANE</small></div></div>
      <nav>{navigation.map(([id, label, icon]) => {const unread=data.events.filter(event=>!event.readAt).length;return <button key={id} onClick={() => setActive(id)} className={active === id ? "active" : ""}><span>{icon}</span>{label}{id === "alerts" && unread > 0 && <b>{unread}</b>}</button>})}</nav>
      <div className="sidebar-foot"><span className="live-dot"/><div><strong>私有控制台</strong><small>D1 数据已持久化</small></div></div>
    </aside>
    <section className="workspace">
      <header><div><p>API 网关管理系统</p><h1>{title}</h1></div><div className="header-actions"><span className={data.gatewayEnabled ? "gateway on" : "gateway off"}>● 网关{data.gatewayEnabled ? "运行中" : "已停止"}</span><button className="icon-button">⌕</button><button className="avatar">孙</button></div></header>
      {notice && <div className="notice"><span>{notice}</span><button onClick={() => setNotice("")}>×</button></div>}
      {active === "overview" && <Overview data={data} loading={loading} onGo={setActive} onAdd={() => setModal("provider")} onToggle={() => action({ action: "toggle-gateway", enabled: !data.gatewayEnabled })}/>} 
      {active === "providers" && <DetailedProviders data={data} action={action} onAdd={() => setModal("provider")} onCredential={p => {setSelectedProvider(p);setModal("credential")}} onModel={p => {setSelectedProvider(p);setModal("model")}} onTest={p => action({action:"test-provider",providerId:p.id})}/>} 
      {active === "models" && <><ModelsPage data={data} action={action}/><SmartPricingPanelV2 data={data} action={action}/></>}
      {active === "members" && <><MembersPage data={data} action={action} onAdd={()=>setModal("member")}/><AccessPolicyPanel data={data} action={action}/></>}
      {active === "invites" && <><InvitesPageV3 data={data} action={action}/><InvitePolicyEditor data={data} action={action}/></>}
      {active === "limits" && <LimitsPageV2 data={data} action={action}/>}
      {active === "calls" && <CallsPage data={data}/>} 
      {active === "audit" && <AuditPage data={data}/>} 
      {active === "alerts" && <Alerts events={data.events} action={action}/>}
      {active === "settings" && <SettingsPage data={data} action={action}/>}
    </section>
    {modal === "provider" && <div className="modal-backdrop"><form className="modal" onSubmit={e => { e.preventDefault(); const t = templates[selectedTemplate]; action({ action: "create-provider", ...t, name: new FormData(e.currentTarget).get("name") || t.name, billingType: new FormData(e.currentTarget).get("billingType") }); }}><div className="modal-head"><div><small>新建连接</small><h2>添加模型提供商</h2></div><button type="button" onClick={() => setModal(null)}>×</button></div><label>平台模板<select value={selectedTemplate} onChange={e => setSelectedTemplate(Number(e.target.value))}>{templates.map((t, i) => <option key={t.name} value={i}>{t.name}</option>)}</select></label><div className="template-preview"><span>{templates[selectedTemplate].protocol}</span><code>{templates[selectedTemplate].baseUrl}</code></div><label>提供商名称<input name="name" defaultValue={templates[selectedTemplate].name}/></label><label>计费类型<select name="billingType"><option value="subscription">套餐 / AFP</option><option value="metered">按量计费</option><option value="internal">内部点数</option></select></label><p className="safe-note">连接创建后进入“待验证”状态。自定义地址必须通过 HTTPS 与公网地址安全校验。</p><div className="modal-actions"><button type="button" onClick={() => setModal(null)}>取消</button><button className="primary">创建提供商</button></div></form></div>}
    {modal === "member" && <div className="modal-backdrop"><form className="modal" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget); action({ action: "create-member", name: f.get("name"), email: f.get("email") }); }}><div className="modal-head"><div><small>访问控制</small><h2>添加成员</h2></div><button type="button" onClick={() => setModal(null)}>×</button></div><label>成员名称<input name="name" required placeholder="例如：开发组"/></label><label>邮箱<input name="email" type="email" placeholder="name@example.com"/></label><p className="safe-note">系统将创建一个个人 API Key，完整 Key 只会显示一次，数据库仅保存不可逆哈希。</p><div className="modal-actions"><button type="button" onClick={() => setModal(null)}>取消</button><button className="primary">创建成员与 Key</button></div></form></div>}
    {modal === "credential" && selectedProvider && <div className="modal-backdrop"><form className="modal" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action({action:"add-credential",providerId:selectedProvider.id,name:f.get("name"),apiKey:f.get("apiKey")})}}><div className="modal-head"><div><small>{selectedProvider.name}</small><h2>添加上游 API Key</h2></div><button type="button" onClick={()=>setModal(null)}>×</button></div><label>Key 名称<input name="name" defaultValue="主 Key" required/></label><label>API Key<input name="apiKey" type="password" autoComplete="off" required placeholder="保存后不可查看明文"/></label><p className="safe-note">密钥使用 AES-256-GCM 加密保存；页面、接口和审计日志只保留脱敏前缀。</p><div className="modal-actions"><button type="button" onClick={()=>setModal(null)}>取消</button><button className="primary">加密保存</button></div></form></div>}
    {modal === "model" && selectedProvider && <div className="modal-backdrop"><form className="modal" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action({action:"create-model",providerId:selectedProvider.id,upstreamModelId:f.get("upstreamModelId"),publicName:f.get("publicName"),contextWindow:Number(f.get("contextWindow")),supportsVision:f.get("supportsVision")==="on"})}}><div className="modal-head"><div><small>{selectedProvider.name}</small><h2>添加模型与公共路由</h2></div><button type="button" onClick={()=>setModal(null)}>×</button></div><label>上游模型 ID<input name="upstreamModelId" required placeholder="deepseek-v4-pro"/></label><label>公共模型名<input name="publicName" required placeholder="deepseek-v4-pro"/></label><label>上下文长度<input name="contextWindow" type="number" defaultValue="128000"/></label><div className="check-row"><label><input name="supportsVision" type="checkbox"/> 支持图片输入</label></div><p className="safe-note">图片请求只会进入已开启“支持图片输入”的模型路由；文字请求不受影响。</p><div className="modal-actions"><button type="button" onClick={()=>setModal(null)}>取消</button><button className="primary">创建模型</button></div></form></div>}
    {modal === "invite" && <div className="modal-backdrop"><form className="modal" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);action({action:"create-invite",email:f.get("email"),note:f.get("note"),validDays:Number(f.get("validDays")),monthlyRequestLimit:Number(f.get("monthlyRequestLimit")),monthlyTokenLimit:Number(f.get("monthlyTokenLimit")),rpmLimit:Number(f.get("rpmLimit")),concurrencyLimit:Number(f.get("concurrencyLimit"))})}}><div className="modal-head"><div><small>USER ONBOARDING</small><h2>创建一次性邀请</h2></div><button type="button" onClick={()=>setModal(null)}>×</button></div><label>受邀邮箱<input name="email" type="email" placeholder="member@example.com"/></label><label>成员备注<input name="note" placeholder="例如：测试成员"/></label><div className="form-grid"><label>有效天数<input name="validDays" type="number" defaultValue="7"/></label><label>月请求额度<input name="monthlyRequestLimit" type="number" defaultValue="100"/></label><label>月 Token 额度<input name="monthlyTokenLimit" type="number" defaultValue="100000"/></label><label>RPM<input name="rpmLimit" type="number" defaultValue="20"/></label><label>并发<input name="concurrencyLimit" type="number" defaultValue="2"/></label></div><div className="modal-actions"><button type="button" onClick={()=>setModal(null)}>取消</button><button className="primary">创建邀请</button></div></form></div>}
  </main>;
}

function Overview({ data, loading, onGo, onAdd, onToggle }: { data: Snapshot; loading: boolean; onGo: (v:string)=>void; onAdd:()=>void; onToggle:()=>void }) {
  const s = data.stats;
  const cards = [["提供商", `${s.healthyProviders}/${s.providers}`, "正常 / 总数", "providers"], ["可用凭证", s.credentials, "加密存储", "providers"], ["已启用模型", s.models, "公共模型路由", "models"], ["今日调用", s.callsToday, `${s.successRate}% 成功率`, "calls"], ["当前并发", s.activeLeases, "自动租约回收", "limits"]];
  return <div className="content"><section className="hero"><div><span className="eyebrow">SYSTEM OVERVIEW</span><h2>网关状态一目了然</h2><p>提供商、密钥池、路由、额度和审计集中管理，默认采用最严格限制。</p></div><div className="hero-actions"><button onClick={onAdd} className="primary">＋ 添加提供商</button><button onClick={onToggle} className={data.gatewayEnabled ? "danger-soft" : "success-soft"}>{data.gatewayEnabled ? "紧急停止" : "恢复网关"}</button></div></section>
    <section className="stats">{cards.map(([label, value, sub, target]) => <button key={String(label)} onClick={() => onGo(String(target))}><small>{label}</small><strong>{loading ? "—" : value}</strong><span>{sub}</span></button>)}</section>
    <section className="grid-main"><article className="panel"><div className="panel-head"><div><small>PROVIDER HEALTH</small><h3>提供商健康度</h3></div><button onClick={() => onGo("providers")}>查看全部 →</button></div>{data.providers.length === 0 ? <Empty text="还没有提供商" action="添加第一个提供商" onClick={onAdd}/> : <div className="provider-health">{data.providers.slice(0,4).map(p => <div key={p.id}><span className={`status-dot ${p.status}`}/><div><strong>{p.name}</strong><small>{p.protocol} · {p.availableCredentials}/{p.credentialCount} Key 可用</small></div><b>{p.status === "healthy" ? "正常" : p.status === "disabled" ? "停用" : "待验证"}</b></div>)}</div>}</article>
      <article className="panel"><div className="panel-head"><div><small>ALERT CENTER</small><h3>需要关注</h3></div><button onClick={() => onGo("alerts")}>告警中心 →</button></div>{data.events.length === 0 ? <div className="all-clear"><span>✓</span><strong>暂无告警</strong><small>系统状态正常</small></div> : <div className="event-list">{data.events.slice(0,4).map(e => <div key={e.id}><span>!</span><div><strong>{e.summary}</strong><small>{e.createdAt}</small></div></div>)}</div>}</article></section>
    <section className="principles"><div><span>01</span><strong>密钥永不回显</strong><small>AES-GCM 密文 + 指纹校验</small></div><div><span>02</span><strong>限制逐层收紧</strong><small>全站到个人 Key 取最严格值</small></div><div><span>03</span><strong>默认禁止跨池回退</strong><small>避免意外产生按量费用</small></div><div><span>04</span><strong>不记录请求正文</strong><small>只保存用量、状态与耗时</small></div></section>
  </div>;
}

function Providers({ data, onAdd, onCredential, onModel, onTest }: { data: Snapshot; onAdd:()=>void; onCredential:(p:Provider)=>void; onModel:(p:Provider)=>void; onTest:(p:Provider)=>void }) { return <div className="content"><div className="toolbar"><div><span className="eyebrow">UPSTREAM REGISTRY</span><h2>独立管理每个协议与 Base URL</h2><p>不同协议或地址始终创建为独立提供商，凭证池和计费池互不混用。</p></div><button className="primary" onClick={onAdd}>＋ 添加提供商</button></div><div className="table-card"><div className="table-filters"><button className="selected">全部 {data.providers.length}</button><button>正常 {data.stats.healthyProviders}</button><button>待验证 {data.providers.filter(p=>p.status==="pending").length}</button><input placeholder="搜索提供商…"/></div>{data.providers.length === 0 ? <Empty text="提供商列表为空" action="从内置模板创建" onClick={onAdd}/> : <div className="table-wrap"><table><thead><tr><th>提供商</th><th>协议 / Base URL</th><th>凭证</th><th>模型</th><th>计费</th><th>状态</th><th>操作</th></tr></thead><tbody>{data.providers.map(p => <tr key={p.id}><td><strong>{p.name}</strong><small>{p.platform}</small></td><td><span>{p.protocol}</span><code>{p.baseUrl}</code></td><td>{p.availableCredentials}/{p.credentialCount} 可用</td><td>{p.modelCount} 个</td><td><span className="pill">{p.billingType === "subscription" ? "套餐" : "按量"}</span></td><td><span className={`status ${p.status}`}>● {p.status === "healthy" ? "正常" : "待验证"}</span></td><td><div className="row-actions"><button onClick={()=>onCredential(p)}>＋Key</button><button onClick={()=>onModel(p)}>＋模型</button><button onClick={()=>onTest(p)}>测试</button></div></td></tr>)}</tbody></table></div>}</div></div> }

type ActionFn=(payload:Record<string,unknown>)=>Promise<void>;
const formObject=(form:HTMLFormElement)=>Object.fromEntries(new FormData(form).entries());

function DetailedProviders({data,action,onAdd,onCredential,onModel,onTest}:{data:Snapshot;action:ActionFn;onAdd:()=>void;onCredential:(p:Provider)=>void;onModel:(p:Provider)=>void;onTest:(p:Provider)=>void}){
  const [open,setOpen]=useState<string|null>(data.providers[0]?.id||null);
  return <div className="content"><div className="toolbar"><div><span className="eyebrow">UPSTREAM REGISTRY</span><h2>模型提供商与配置明细</h2><p>展开提供商即可查看并维护基本参数、API Key、上游模型与本站计量。</p></div><button className="primary" onClick={onAdd}>＋ 添加提供商</button></div>{data.providers.length===0?<div className="table-card"><Empty text="提供商列表为空" action="从内置模板创建" onClick={onAdd}/></div>:<div className="entity-stack">{data.providers.map(provider=>{const keys=data.credentials.filter(key=>key.providerId===provider.id);const models=data.models.filter(model=>model.providerId===provider.id);return <article className="entity-card" key={provider.id}><button className="entity-summary" onClick={()=>setOpen(open===provider.id?null:provider.id)}><div><strong>{provider.name}</strong><small>{provider.protocol} · {provider.baseUrl}</small></div><div className="entity-badges"><span>{keys.length} Key</span><span>{models.length} 模型</span><span className={`status ${provider.status}`}>● {provider.status}</span><b>{open===provider.id?"收起":"展开"}</b></div></button>{open===provider.id&&<div className="entity-detail"><section className="subsection"><div className="subsection-head"><div><h3>本站近 30 天计量</h3><small>{provider.usedRequests30d.toLocaleString()} 次请求 · {provider.usedTokens30d.toLocaleString()} Token{provider.billingType==="subscription"?` · 本地套餐结算 ${provider.localCost30d.toFixed(4)}`:""}</small></div></div><p className="safe-note">这里只统计经过本站网关并成功写入账本的调用；供应商控制台还可能包含直连调用，套餐 AFP/点数也不能与 Token 直接比较。</p>{provider.meteringGaps30d>0&&<p className="error-note">发现 {provider.meteringGaps30d} 条历史成功调用未记录 Token（多为旧版流式请求），历史值无法精确反推；新请求已修复。</p>}</section><form className="config-form" onSubmit={e=>{e.preventDefault();action({action:"update-provider",id:provider.id,...formObject(e.currentTarget)})}}><h3>基本配置</h3><div className="form-grid"><label>名称<input name="name" defaultValue={provider.name}/></label><label>状态<select name="status" defaultValue={provider.status}><option value="healthy">正常</option><option value="pending">待验证</option><option value="disabled">停用</option></select></label><label>并发上限<input name="concurrencyLimit" type="number" defaultValue={provider.concurrencyLimit}/></label><label>RPM<input name="rpmLimit" type="number" defaultValue={provider.rpmLimit}/></label><label>TPM<input name="tpmLimit" type="number" defaultValue={provider.tpmLimit}/></label><label>超时毫秒<input name="timeoutMs" type="number" defaultValue={provider.timeoutMs}/></label></div><div className="inline-actions"><button className="primary">保存基本配置</button><button type="button" onClick={()=>onTest(provider)}>测试连接</button><button type="button" className="danger-link" onClick={()=>confirm("确认停用此提供商及其 Key、模型？")&&action({action:"delete-provider",id:provider.id})}>停用提供商</button></div></form><section className="subsection"><div className="subsection-head"><div><h3>API Key</h3><small>完整密钥永不回显</small></div><button onClick={()=>onCredential(provider)}>＋ 添加 Key</button></div>{keys.length===0?<p className="sub-empty">尚未添加 Key</p>:keys.map(key=><details className="config-row" key={key.id}><summary><span><strong>{key.name}</strong><small>{key.prefix}</small></span><span>{key.status} · 优先级 {key.priority} · 并发 {key.concurrencyLimit}</span></summary><form onSubmit={e=>{e.preventDefault();action({action:"update-credential",id:key.id,...formObject(e.currentTarget)})}}><div className="form-grid"><label>名称<input name="name" defaultValue={key.name}/></label><label>状态<select name="status" defaultValue={key.status}><option value="available">可用</option><option value="pending">待验证</option><option value="disabled">停用</option></select></label><label>优先级<input name="priority" type="number" defaultValue={key.priority}/></label><label>权重<input name="weight" type="number" defaultValue={key.weight}/></label><label>并发<input name="concurrencyLimit" type="number" defaultValue={key.concurrencyLimit}/></label><label>RPM<input name="rpmLimit" type="number" defaultValue={key.rpmLimit}/></label><label>TPM<input name="tpmLimit" type="number" defaultValue={key.tpmLimit}/></label></div>{key.lastError&&<p className="error-note">最近错误：{key.lastError}</p>}<div className="inline-actions"><button className="primary">保存 Key 配置</button><button type="button" className="danger-link" onClick={()=>confirm("确认删除此 Key？")&&action({action:"delete-credential",id:key.id})}>删除 Key</button></div></form></details>)}</section><section className="subsection"><div className="subsection-head"><div><h3>上游模型与路由</h3><small>公共模型名称与上游 ID 独立</small></div><button onClick={()=>onModel(provider)}>＋ 添加模型</button></div>{models.length===0?<p className="sub-empty">尚未添加模型</p>:models.map(model=><ModelEditor key={model.id} model={model} action={action}/>)}</section></div>}</article>})}</div>}</div>
}

function ModelEditor({model,action}:{model:Model;action:ActionFn}){return <details className="config-row"><summary><span><strong>{model.publicName}</strong><small>{model.upstreamModelId}</small></span><span>{model.status} · {model.supportsVision?"支持图片 · ":""}上下文 {model.contextWindow.toLocaleString()} · 并发 {model.routeConcurrency}</span></summary><form onSubmit={e=>{e.preventDefault();const values=formObject(e.currentTarget);action({action:"update-model",id:model.id,routeId:model.routeId,...values,supportsChat:Boolean(values.supportsChat),supportsStreaming:Boolean(values.supportsStreaming),supportsTools:Boolean(values.supportsTools),supportsVision:Boolean(values.supportsVision),allowFailover:Boolean(values.allowFailover)})}}><div className="form-grid"><label>显示名称<input name="displayName" defaultValue={model.displayName}/></label><label>上游模型 ID<input name="upstreamModelId" defaultValue={model.upstreamModelId}/></label><label>状态<select name="status" defaultValue={model.status}><option value="enabled">启用</option><option value="disabled">停用</option></select></label><label>上下文<input name="contextWindow" type="number" defaultValue={model.contextWindow}/></label><label>最大输出<input name="maxOutputTokens" type="number" defaultValue={model.maxOutputTokens}/></label><label>路由优先级<input name="routePriority" type="number" defaultValue={model.routePriority}/></label><label>路由并发<input name="routeConcurrency" type="number" defaultValue={model.routeConcurrency}/></label></div><div className="check-row"><label><input name="supportsChat" type="checkbox" defaultChecked={model.supportsChat}/> Chat</label><label><input name="supportsStreaming" type="checkbox" defaultChecked={model.supportsStreaming}/> 流式</label><label><input name="supportsTools" type="checkbox" defaultChecked={model.supportsTools}/> 工具调用</label><label><input name="supportsVision" type="checkbox" defaultChecked={model.supportsVision}/> 图片输入</label><label><input name="allowFailover" type="checkbox" defaultChecked={model.allowFailover}/> 允许故障转移</label></div><div className="inline-actions"><button className="primary">保存模型配置</button><button type="button" className="danger-link" onClick={()=>confirm("确认停用此模型及路由？")&&action({action:"delete-model",id:model.id})}>停用模型</button></div></form></details>}

function ModelsPage({data,action}:{data:Snapshot;action:ActionFn}){return <div className="content"><div className="toolbar"><div><span className="eyebrow">MODEL REGISTRY</span><h2>模型与路由</h2><p>查看公共名称、上游 ID、能力和路由限制；展开后可编辑或停用。</p></div></div><div className="table-card list-pad">{data.models.length===0?<p className="sub-empty">暂无模型，请从模型提供商中添加</p>:data.models.map(model=><ModelEditor key={model.id} model={model} action={action}/>)}</div></div>}

function MembersPage({data,action,onAdd}:{data:Snapshot;action:ActionFn;onAdd:()=>void}){return <div className="content"><div className="toolbar"><div><span className="eyebrow">MEMBER CONTROL</span><h2>成员、个人 Key 与额度</h2><p>展开成员即可维护状态、月度额度、速率与并发，并模拟调用验证策略。</p></div><button className="primary" onClick={onAdd}>＋ 添加成员</button></div><div className="entity-stack">{data.members.length===0?<div className="table-card"><Empty text="还没有成员" action="添加成员" onClick={onAdd}/></div>:data.members.map(member=><article className="entity-card" key={member.id}><details><summary className="entity-summary"><div><strong>{member.name}</strong><small>{member.email||"未绑定邮箱"}</small></div><div className="entity-badges"><span>{member.keys.length} Key</span><span>有效请求 {member.quotaStatus==="expired"?"无有效卡密":member.effectiveRequestLimit??"不限"}</span><span>并发 {member.concurrencyLimit}</span><b>{member.status}</b></div></summary><div className="entity-detail">{member.quotaSource==="card"&&<section className="subsection"><div className="subsection-head"><div><h3>卡密生效额度</h3><small>{member.quotaStatus==="active"?`${member.usedRequests.toLocaleString()} / ${member.effectiveRequestLimit??"不限"} 次 · ${member.usedTokens.toLocaleString()} / ${member.effectiveTokenLimit??"不限"} Token`:"当前没有有效卡密额度"}</small></div></div>{member.quotaStatus==="active"?<p className="safe-note">{member.activeEntitlementCount} 份有效额度叠加 · 生效至 {member.entitlementExpiresAt?new Date(member.entitlementExpiresAt).toLocaleString("zh-CN",{hour12:false}):"—"}</p>:<p className="error-note">卡密额度已过期，网关会拒绝调用；请为成员兑换新卡密。</p>}</section>}<form className="config-form" onSubmit={e=>{e.preventDefault();action({action:"update-member",id:member.id,...formObject(e.currentTarget)})}}><div className="form-grid"><label>名称<input name="name" defaultValue={member.name}/></label><label>邮箱<input name="email" type="email" defaultValue={member.email||""}/></label><label>状态<select name="status" defaultValue={member.status}><option value="active">正常</option><option value="paused">暂停</option></select></label><label>管理员额外月请求上限<input name="monthlyRequestLimit" type="number" defaultValue={member.monthlyRequestLimit??""}/></label><label>管理员额外月 Token 上限<input name="monthlyTokenLimit" type="number" defaultValue={member.monthlyTokenLimit??""}/></label><label>RPM<input name="rpmLimit" type="number" defaultValue={member.rpmLimit}/></label><label>TPM<input name="tpmLimit" type="number" defaultValue={member.tpmLimit}/></label><label>并发<input name="concurrencyLimit" type="number" defaultValue={member.concurrencyLimit}/></label></div><div className="inline-actions"><button className="primary">保存成员策略</button><button type="button" className="danger-link" onClick={()=>confirm("确认删除成员并撤销全部个人 Key？")&&action({action:"delete-member",id:member.id})}>删除成员</button></div></form><section className="subsection"><h3>个人 API Key</h3>{member.keys.map(key=><div className="key-line" key={key.id}><span><strong>{key.name}</strong><small>{key.prefix} · {key.status}</small></span><button onClick={()=>action({action:"toggle-member-key",id:key.id,status:key.status==="active"?"paused":"active"})}>{key.status==="active"?"暂停":"启用"}</button></div>)}</section><form className="simulation" onSubmit={e=>{e.preventDefault();action({action:"simulate-usage",memberId:member.id,...formObject(e.currentTarget)})}}><div><h3>模拟用户调用</h3><p>不发送提示词到上游，仅验证额度并写入调用账本。</p></div><label>模型<select name="model">{data.models.map(model=><option key={model.id}>{model.publicName}</option>)}<option>simulation-model</option></select></label><label>输入 Token<input name="inputTokens" type="number" defaultValue="100"/></label><label>输出 Token<input name="outputTokens" type="number" defaultValue="50"/></label><button className="primary">执行模拟</button></form></div></details></article>)}</div></div>}

function InvitesPage({data,action,onAdd}:{data:Snapshot;action:ActionFn;onAdd:()=>void}){return <div className="content"><div className="toolbar"><div><span className="eyebrow">USER ONBOARDING</span><h2>邀请管理</h2><p>创建一次性邀请，模拟受邀用户兑换并自动生成成员和个人 Key。</p></div><button className="primary" onClick={onAdd}>＋ 创建邀请</button></div><div className="table-card"><div className="table-wrap"><table><thead><tr><th>兑换码</th><th>邮箱 / 备注</th><th>默认额度</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody>{data.invitations.map(invite=><tr key={invite.id}><td><code>{invite.code}</code></td><td><strong>{invite.email||"未绑定"}</strong><small>{invite.note}</small></td><td>{invite.monthlyRequestLimit??"不限"} 请求<small>{invite.monthlyTokenLimit??"不限"} Token · 并发 {invite.concurrencyLimit}</small></td><td>{new Date(invite.expiresAt).toLocaleString("zh-CN",{hour12:false})}</td><td>{invite.status}</td><td><div className="row-actions">{invite.status==="pending"&&<><button onClick={()=>action({action:"redeem-invite",id:invite.id,name:invite.note||invite.email||"受邀成员"})}>模拟兑换</button><button onClick={()=>action({action:"revoke-invite",id:invite.id})}>撤销</button></>}</div></td></tr>)}</tbody></table>{data.invitations.length===0&&<p className="sub-empty">暂无邀请</p>}</div></div></div>}

function LimitsPage({data}:{data:Snapshot}){return <div className="content"><div className="toolbar"><div><span className="eyebrow">POLICY EFFECTIVE VIEW</span><h2>额度与流量控制</h2><p>这里展示当前配置的限制；成员模拟调用和真实网关请求都会按最严格值校验。</p></div></div><section className="metric-row"><div><small>全站并发占用</small><strong>{data.stats.activeLeases}</strong><span>自动租约回收</span></div><div><small>提供商并发总量</small><strong>{data.providers.length*10}</strong><span>默认值汇总</span></div><div><small>成员月请求额度</small><strong>{data.members.filter(m=>m.monthlyRequestLimit).length}</strong><span>已配置成员</span></div><div><small>成员 Token 额度</small><strong>{data.members.filter(m=>m.monthlyTokenLimit).length}</strong><span>已配置成员</span></div></section><div className="table-card"><div className="table-wrap"><table><thead><tr><th>成员</th><th>状态</th><th>月请求</th><th>月 Token</th><th>RPM / TPM</th><th>并发</th></tr></thead><tbody>{data.members.map(member=><tr key={member.id}><td>{member.name}</td><td>{member.status}</td><td>{member.monthlyRequestLimit??"不限"}</td><td>{member.monthlyTokenLimit??"不限"}</td><td>{member.rpmLimit} / {member.tpmLimit}</td><td>{member.concurrencyLimit}</td></tr>)}</tbody></table></div></div></div>}

function InvitesPageV2({data,action}:{data:Snapshot;action:ActionFn}){
  return <div className="content"><div className="toolbar"><div><span className="eyebrow">CARD ACCESS</span><h2>卡密与邀请管理</h2><p>批量生成一次性卡密，用户在公开用户中心绑定邮箱；未兑换卡密可随时撤销。</p></div><a className="primary link-button" href="/portal" target="_blank">打开用户端 ↗</a></div><article className="table-card policy-panel"><div className="policy-grid"><form onSubmit={e=>{e.preventDefault();action({action:"batch-create-invites",...formObject(e.currentTarget)})}}><h3>批量生成卡密</h3><div className="form-grid"><label>数量<input name="quantity" type="number" min="1" max="100" defaultValue="10"/></label><label>有效天数<input name="validDays" type="number" min="1" defaultValue="30"/></label><label>请求额度<input name="monthlyRequestLimit" type="number" placeholder="不限则留空"/></label><label>Token 额度<input name="monthlyTokenLimit" type="number" placeholder="不限则留空"/></label><label>RPM<input name="rpmLimit" type="number" defaultValue="60"/></label><label>并发<input name="concurrencyLimit" type="number" defaultValue="2"/></label></div><label>批次备注<input name="note" defaultValue="线下卡密"/></label><button className="primary">生成卡密</button></form><div className="quota-explain"><h3>用户使用流程</h3><ol><li>管理员生成卡密并线下发给用户。</li><li>用户打开用户端，输入邮箱和卡密完成绑定。</li><li>用户查看额度、有效期、模型和 Base URL。</li><li>额度到期前后可兑换新卡密续充。</li></ol></div></div></article><div className="table-card"><div className="table-wrap"><table><thead><tr><th>卡密</th><th>绑定邮箱</th><th>额度</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody>{data.invitations.map(invite=><tr key={invite.id}><td><code>{invite.code}</code><small>{invite.note}</small></td><td>{invite.email||"尚未绑定"}</td><td>{invite.monthlyRequestLimit??"不限"} 次<small>{invite.monthlyTokenLimit??"不限"} Token</small></td><td>{new Date(invite.expiresAt).toLocaleString("zh-CN",{hour12:false})}</td><td><span className={invite.status==="pending"?"status healthy":"status"}>● {invite.status}</span></td><td>{invite.status==="pending"&&<button className="danger-link" onClick={()=>confirm("确认将这张卡密置为无效？")&&action({action:"revoke-invite",id:invite.id})}>置为无效</button>}</td></tr>)}</tbody></table>{data.invitations.length===0&&<p className="sub-empty">暂无卡密</p>}</div></div></div>
}

function InvitesPageV3({data,action}:{data:Snapshot;action:ActionFn}){
  const [tokenValue,setTokenValue]=useState("");
  const [validDays,setValidDays]=useState("30");
  const [createdAtPreview]=useState(()=>Date.now());
  const tokenDescription=(raw:string)=>{
    const value=Number(raw);
    if(!Number.isFinite(value)||value<=0)return "留空表示不限制 Token 总量";
    const trim=(number:number)=>number.toFixed(2).replace(/\.00$/,"").replace(/(\.\d)0$/,"$1");
    if(value>=100000000)return `${trim(value/100000000)} 亿 Token（${value.toLocaleString("zh-CN")} Token）`;
    if(value>=10000)return `${trim(value/10000)} 万 Token（${value.toLocaleString("zh-CN")} Token）`;
    return `${value.toLocaleString("zh-CN")} Token`;
  };
  const days=Math.max(1,Number(validDays)||1);
  const expiryPreview=new Date(createdAtPreview+days*86400000).toLocaleString("zh-CN",{hour12:false});
  return <div className="content">
    <div className="toolbar"><div><span className="eyebrow">CARD ACCESS</span><h2>卡密与邀请管理</h2><p>批量生成一次性卡密，用户在公开用户中心绑定邮箱；未兑换卡密可随时撤销。</p></div><a className="primary link-button" href="/portal" target="_blank">打开用户端 ↗</a></div>
    <article className="table-card policy-panel"><div className="policy-grid">
      <form onSubmit={e=>{e.preventDefault();action({action:"batch-create-invites",...formObject(e.currentTarget)})}}>
        <h3>批量生成卡密</h3>
        <div className="form-grid">
          <label>生成数量 <span className="unit-tag">张</span><input name="quantity" type="number" min="1" max="100" defaultValue="10"/><small className="field-help">一次最多生成 100 张</small></label>
          <label>有效期 <span className="unit-tag">天</span><input name="validDays" type="number" min="1" value={validDays} onChange={e=>setValidDays(e.target.value)}/><small className="field-help">{days}×24 小时，预计 {expiryPreview} 到期</small></label>
          <label>请求额度 <span className="unit-tag">次</span><input name="monthlyRequestLimit" type="number" min="1" placeholder="例如 1000"/><small className="field-help">每成功发起一次 API 调用计 1 次；留空不限</small></label>
          <label>Token 额度 <span className="unit-tag">Token</span><input name="monthlyTokenLimit" type="number" min="1" value={tokenValue} onChange={e=>setTokenValue(e.target.value)} placeholder="例如 1000000"/><small className="field-help token-translation">= {tokenDescription(tokenValue)}</small></label>
          <label>RPM <span className="unit-tag">次/分钟</span><input name="rpmLimit" type="number" defaultValue="60"/><small className="field-help">每分钟最大请求次数</small></label>
          <label>并发 <span className="unit-tag">请求</span><input name="concurrencyLimit" type="number" defaultValue="2"/><small className="field-help">同一时刻最大在途请求数</small></label>
        </div>
        <div className="expiry-rule"><strong>到期规则</strong><span>从卡密生成时刻起精确计算 {days}×24 小时，不延长到到期日的 23:59:59。到期时间会写入卡密并在列表中显示。</span></div>
        <label>批次备注<input name="note" defaultValue="线下卡密"/></label>
        <button className="primary">生成卡密</button>
      </form>
      <div className="quota-explain"><h3>额度单位说明</h3><p><strong>请求额度（次）</strong>：允许调用 API 的总次数，例如 1000 表示最多请求 1000 次。</p><p><strong>Token 额度（Token）</strong>：输入 Token 与输出 Token 的累计总量。填写 1000000 即 100 万 Token，不是“1 个百万单位”。</p><p><strong>先到先停</strong>：请求次数、Token 或有效期任意一个先达到限制，网关都会停止放行。</p><p><strong>有效期</strong>：按生成时间点精确到期。例如 8 月 21 日 15:30 生成，30 天后为 9 月 20 日 15:30 到期。</p></div>
    </div></article>
    <div className="table-card"><div className="table-wrap"><table><thead><tr><th>卡密</th><th>绑定邮箱</th><th>额度</th><th>精确到期时间</th><th>状态</th><th>操作</th></tr></thead><tbody>{data.invitations.map(invite=><tr key={invite.id}><td><code>{invite.code}</code><small>{invite.note}</small></td><td>{invite.email||"尚未绑定"}</td><td>{invite.monthlyRequestLimit??"不限"} 次<small>{invite.monthlyTokenLimit?tokenDescription(String(invite.monthlyTokenLimit)):"Token 不限"}</small></td><td>{new Date(invite.expiresAt).toLocaleString("zh-CN",{hour12:false})}<small>按生成时刻计算</small></td><td><span className={invite.status==="pending"?"status healthy":"status"}>● {invite.status}</span></td><td>{invite.status==="pending"&&<button className="danger-link" onClick={()=>confirm("确认将这张卡密置为无效？")&&action({action:"revoke-invite",id:invite.id})}>置为无效</button>}</td></tr>)}</tbody></table>{data.invitations.length===0&&<p className="sub-empty">暂无卡密</p>}</div></div>
  </div>;
}

function LimitsPageV2({data,action}:{data:Snapshot;action:ActionFn}){
  const windowName=(seconds:number)=>seconds===3600?"近 1 小时":seconds===18000?"近 5 小时":seconds===604800?"近 1 周":seconds===2592000?"近 30 天":`${seconds} 秒`;
  return <div className="content"><div className="toolbar"><div><span className="eyebrow">QUOTA POLICY ENGINE</span><h2>额度规则维护</h2><p>请求额度限制调用次数；Token 额度限制输入与输出 Token 总量。多条规则同时命中时采用最严格结果。</p></div></div><section className="metric-row"><div><small>额度规则</small><strong>{data.quotaRules.length}</strong><span>启用 {data.quotaRules.filter(rule=>rule.enabled).length}</span></div><div><small>全站并发占用</small><strong>{data.stats.activeLeases}</strong><span>自动租约回收</span></div><div><small>提供商并发总量</small><strong>{data.providers.reduce((sum,item)=>sum+item.concurrencyLimit,0)}</strong><span>在模型提供商维护</span></div><div><small>受控成员</small><strong>{new Set(data.quotaRules.map(rule=>rule.memberId||"all")).size}</strong><span>全体或指定成员</span></div></section><article className="table-card policy-panel"><div className="policy-grid quota-builder"><form onSubmit={e=>{e.preventDefault();action({action:"save-quota-rule",...formObject(e.currentTarget)})}}><h3>新增额度规则</h3><label>规则名称<input name="name" required placeholder="例如：全体成员 5 小时保护"/></label><div className="form-grid"><label>统计窗口<select name="windowSeconds" defaultValue="18000"><option value="3600">近 1 小时</option><option value="18000">近 5 小时</option><option value="604800">近 1 周</option><option value="2592000">近 30 天</option></select></label><label>请求额度<input name="requestLimit" type="number" min="1" placeholder="不限制则留空"/></label><label>Token 额度<input name="tokenLimit" type="number" min="1" placeholder="不限制则留空"/></label><label>成员范围<select name="memberId"><option value="">全体成员（逐成员计算）</option>{data.members.map(member=><option key={member.id} value={member.id}>{member.name}</option>)}</select></label><label>提供商范围<select name="providerId"><option value="">全部提供商</option>{data.providers.map(provider=><option key={provider.id} value={provider.id}>{provider.name}</option>)}</select></label></div><button className="primary">保存并立即生效</button></form><div className="quota-explain"><h3>口径说明</h3><p><strong>请求额度</strong>：窗口内最多允许多少次 API 调用，适合控制请求频率和套餐次数。</p><p><strong>Token 额度</strong>：窗口内输入 Token + 输出 Token 的总量，适合控制真实资源消耗。</p><p><strong>范围</strong>：全体成员按每个成员分别统计；指定提供商时，只累计该提供商产生的用量。</p><p><strong>并发</strong>：提供商级并发已经放在“模型提供商 → 基本配置”中维护。</p></div></div></article><article className="table-card quota-rule-list"><div className="panel-head"><div><small>EFFECTIVE RULES</small><h3>已配置规则</h3></div></div>{data.quotaRules.length===0?<p className="sub-empty">暂无规则</p>:data.quotaRules.map(rule=>{const member=data.members.find(item=>item.id===rule.memberId),provider=data.providers.find(item=>item.id===rule.providerId);return <div className="quota-rule" key={rule.id}><div><strong>{rule.name}</strong><small>{windowName(rule.windowSeconds)} · {member?.name||"全体成员"} · {provider?.name||"全部提供商"}</small><span>请求 {rule.requestLimit??"不限"} · Token {rule.tokenLimit??"不限"}</span></div><div><span className={rule.enabled?"status healthy":"status"}>● {rule.enabled?"生效中":"已停用"}</span><button onClick={()=>action({action:"save-quota-rule",...rule,enabled:!rule.enabled})}>{rule.enabled?"停用":"启用"}</button><button className="danger-link" onClick={()=>confirm("确认删除此额度规则？")&&action({action:"delete-quota-rule",id:rule.id})}>删除</button></div></div>})}</article><QuotaVerification data={data}/></div>
}

function CallsPage({data}:{data:Snapshot}){return <div className="content"><div className="toolbar"><div><span className="eyebrow">USAGE LEDGER</span><h2>调用记录</h2><p>只记录路由、Token、状态和耗时，不保存提示词或回答正文。</p></div></div><div className="table-card"><div className="table-wrap"><table><thead><tr><th>时间</th><th>模型</th><th>成员</th><th>Token</th><th>状态</th><th>HTTP / 耗时</th></tr></thead><tbody>{data.calls.map(call=><tr key={call.id}><td>{new Date(call.createdAt).toLocaleString("zh-CN",{hour12:false})}</td><td><strong>{call.publicModel}</strong><small>{call.upstreamModel}</small></td><td><code>{call.memberId?.slice(0,8)||"系统"}</code></td><td>{call.inputTokens} + {call.outputTokens}</td><td>{call.status}</td><td>{call.httpStatus??"—"} / {call.durationMs??"—"}ms</td></tr>)}</tbody></table>{data.calls.length===0&&<p className="sub-empty">暂无调用记录</p>}</div></div></div>}

function AuditPage({data}:{data:Snapshot}){return <div className="content"><div className="toolbar"><div><span className="eyebrow">AUDIT TRAIL</span><h2>审计日志</h2><p>记录管理员对提供商、Key、模型、邀请、成员和额度的变更。</p></div></div><div className="table-card"><div className="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>对象</th><th>摘要</th><th>结果</th></tr></thead><tbody>{data.audits.map(audit=><tr key={audit.id}><td>{new Date(audit.createdAt).toLocaleString("zh-CN",{hour12:false})}</td><td>{audit.actor}</td><td><code>{audit.action}</code></td><td>{audit.objectType}</td><td>{audit.summary}</td><td>{audit.result}</td></tr>)}</tbody></table></div></div></div>}

function AccessPolicyPanel({data,action}:{data:Snapshot;action:ActionFn}){return <div className="content compact-content"><article className="table-card policy-panel"><div className="panel-head"><div><small>ACCESS CONTROL</small><h3>个人 Key 与模型权限</h3></div></div><div className="policy-grid"><form onSubmit={e=>{e.preventDefault();action({action:"create-member-key",...formObject(e.currentTarget)})}}><h3>创建成员个人 Key</h3><label>成员<select name="memberId">{data.members.map(member=><option value={member.id} key={member.id}>{member.name}</option>)}</select></label><label>Key 名称<input name="name" defaultValue="业务 Key"/></label><div className="form-grid"><label>RPM<input name="rpmLimit" type="number" defaultValue="20"/></label><label>TPM<input name="tpmLimit" type="number" defaultValue="50000"/></label><label>并发<input name="concurrencyLimit" type="number" defaultValue="1"/></label></div><button className="primary">创建 Key</button></form><form onSubmit={e=>{e.preventDefault();action({action:"set-member-model-policy",...formObject(e.currentTarget)})}}><h3>设置成员模型权限</h3><label>成员<select name="memberId">{data.members.map(member=><option value={member.id} key={member.id}>{member.name}</option>)}</select></label><label>公共模型<select name="publicModelId">{data.publicModels.map(model=><option value={model.id} key={model.id}>{model.name}</option>)}</select></label><label>权限<select name="effect"><option value="allow">允许（清除禁止规则）</option><option value="deny">禁止</option></select></label><button className="primary">保存权限</button><p className="safe-note">已配置 {data.memberPolicies.length} 条禁止规则；真实网关请求会返回 403。</p></form></div></article></div>}

function QuotaVerification({data}:{data:Snapshot}){return <div className="content compact-content"><article className="table-card"><div className="panel-head"><div><small>QUOTA VERIFICATION</small><h3>成员有效额度核对</h3></div></div><div className="table-wrap"><table><thead><tr><th>成员</th><th>请求用量</th><th>Token 用量</th><th>当前判断</th></tr></thead><tbody>{data.members.map(member=>{const requestBlocked=Boolean(member.effectiveRequestLimit&&member.usedRequests>=member.effectiveRequestLimit);const tokenBlocked=Boolean(member.effectiveTokenLimit&&member.usedTokens>=member.effectiveTokenLimit);return <tr key={member.id}><td>{member.name}<small>{member.quotaSource==="card"?"卡密额度周期":"自然月"}</small></td><td>{member.usedRequests} / {member.effectiveRequestLimit??"不限"}</td><td>{member.usedTokens} / {member.effectiveTokenLimit??"不限"}</td><td><span className={member.quotaStatus==="expired"||requestBlocked||tokenBlocked?"status":"status healthy"}>● {member.quotaStatus==="expired"?"额度已过期":requestBlocked||tokenBlocked?"已触发限制":"可调用"}</span></td></tr>})}</tbody></table></div></article></div>}

type PriceConfig={schema:string;model:string;providerModelId:string;billingKind:string;currency:string;unit:string;inputPrice:string;outputPrice:string;cacheInputPrice:string;userInputPrice:string;userOutputPrice:string;sourceNote:string};
const blankPrice=(model?:Model):PriceConfig=>({schema:"aethergate.price.v1",model:model?.upstreamModelId||"",providerModelId:model?.id||"",billingKind:"metered",currency:"USD",unit:"1M_tokens",inputPrice:"",outputPrice:"",cacheInputPrice:"",userInputPrice:"",userOutputPrice:"",sourceNote:""});

function decodePriceConfigs(source:string):Partial<PriceConfig>[] {
  const trimmed=source.trim();
  if(!trimmed)throw new Error("请先粘贴价格配置");
  const fenced=[...trimmed.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)].map(match=>match[1].trim()).filter(Boolean);
  const chunks=fenced.length?fenced:[trimmed];
  const configs:Partial<PriceConfig>[]=[];
  for(const chunk of chunks){
    const decoded=JSON.parse(chunk) as Partial<PriceConfig>|Partial<PriceConfig>[]|{prices?:Partial<PriceConfig>[];configs?:Partial<PriceConfig>[];config?:Partial<PriceConfig>};
    if(Array.isArray(decoded))configs.push(...decoded);
    else if(Array.isArray(decoded.prices))configs.push(...decoded.prices);
    else if(Array.isArray(decoded.configs))configs.push(...decoded.configs);
    else if(decoded.config)configs.push(decoded.config);
    else configs.push(decoded as Partial<PriceConfig>);
  }
  if(!configs.length)throw new Error("没有识别到价格配置");
  return configs;
}

const canonicalModelName=(value:unknown)=>String(value||"").trim().toLowerCase().replace(/\s*\([^)]*\)\s*$/,"");

function SmartPricingPanel({data,action}:{data:Snapshot;action:ActionFn}){
  const [config,setConfig]=useState<PriceConfig>(()=>blankPrice(data.models[0]));
  const [sampleInput,setSampleInput]=useState("1000000");
  const [sampleOutput,setSampleOutput]=useState("1000000");
  const [importText,setImportText]=useState("");
  const [toolNotice,setToolNotice]=useState("");
  useEffect(()=>{if(!config.providerModelId&&data.models[0])queueMicrotask(()=>setConfig(blankPrice(data.models[0])))},[config.providerModelId,data.models]);
  const num=(value:string)=>Number(value)||0;
  const cost=num(config.inputPrice)*num(sampleInput)/1000000+num(config.outputPrice)*num(sampleOutput)/1000000;
  const revenue=num(config.userInputPrice)*num(sampleInput)/1000000+num(config.userOutputPrice)*num(sampleOutput)/1000000;
  const profit=revenue-cost;
  const margin=revenue>0?profit/revenue*100:0;
  const markup=cost>0?profit/cost*100:0;
  const update=(key:keyof PriceConfig,value:string)=>setConfig(current=>({...current,[key]:value}));
  const copyConfig=async()=>{const text=JSON.stringify(config,null,2);setImportText(text);try{await navigator.clipboard.writeText(text);setToolNotice("当前配置已复制") }catch{setToolNotice("配置已生成，请手动复制文本框内容")}};
  const importConfig=()=>{try{const parsed=JSON.parse(importText) as Partial<PriceConfig>;if(parsed.schema!=="aethergate.price.v1")throw new Error();const matched=data.models.find(model=>model.id===parsed.providerModelId||model.upstreamModelId===parsed.model||model.publicName===parsed.model);setConfig({...blankPrice(matched||data.models[0]),...parsed,providerModelId:matched?.id||parsed.providerModelId||"",model:matched?.upstreamModelId||parsed.model||""});setToolNotice(matched?"配置已导入并匹配模型":"配置已导入，请手动选择模型")}catch{setToolNotice("配置格式无效，请粘贴 aethergate.price.v1 JSON")}};
  return <div className="content compact-content"><article className="table-card policy-panel"><div className="panel-head"><div><small>SMART PRICE CONFIG</small><h3>价格、利润测算与一键配置</h3></div><span className="alert-total">标准格式：aethergate.price.v1</span></div><div className="smart-price-layout"><form className="smart-price-form" onSubmit={e=>{e.preventDefault();action({action:"create-price-version",...config})}}><h3>创建价格新版本</h3><label>提供商模型<select value={config.providerModelId} onChange={e=>{const model=data.models.find(item=>item.id===e.target.value);setConfig(current=>({...current,providerModelId:e.target.value,model:model?.upstreamModelId||""}))}}>{data.models.map(model=><option value={model.id} key={model.id}>{model.publicName} → {model.upstreamModelId}</option>)}</select></label><div className="form-grid"><label>计费类型<select value={config.billingKind} onChange={e=>update("billingKind",e.target.value)}><option value="metered">按量</option><option value="subscription">套餐 / AFP</option></select></label><label>币种<input value={config.currency} onChange={e=>update("currency",e.target.value)}/></label><label>单位<input value={config.unit} onChange={e=>update("unit",e.target.value)}/></label><label>上游输入成本<input type="number" step="0.000001" value={config.inputPrice} onChange={e=>update("inputPrice",e.target.value)}/></label><label>上游输出成本<input type="number" step="0.000001" value={config.outputPrice} onChange={e=>update("outputPrice",e.target.value)}/></label><label>缓存输入成本<input type="number" step="0.000001" value={config.cacheInputPrice} onChange={e=>update("cacheInputPrice",e.target.value)}/></label><label>用户输入售价<input type="number" step="0.000001" value={config.userInputPrice} onChange={e=>update("userInputPrice",e.target.value)}/></label><label>用户输出售价<input type="number" step="0.000001" value={config.userOutputPrice} onChange={e=>update("userOutputPrice",e.target.value)}/></label></div><label>价格来源备注<input value={config.sourceNote} onChange={e=>update("sourceNote",e.target.value)} placeholder="官方价格、上下文分段与核对日期"/></label><div className="inline-actions"><button className="primary">创建并生效</button><button type="button" onClick={copyConfig}>复制当前配置</button></div><p className="safe-note">修改价格会创建新版本，旧版本自动失效，历史调用不会重算。</p></form><aside className="profit-panel"><div><span>利润测算</span><h3>差价 = 用户售价 − 上游成本</h3></div><div className="sample-grid"><label>示例输入 Token<input type="number" value={sampleInput} onChange={e=>setSampleInput(e.target.value)}/></label><label>示例输出 Token<input type="number" value={sampleOutput} onChange={e=>setSampleOutput(e.target.value)}/></label></div><div className="profit-metrics"><div><small>预计成本</small><strong>{cost.toFixed(6)} {config.currency}</strong></div><div><small>预计收入</small><strong>{revenue.toFixed(6)} {config.currency}</strong></div><div className={profit>=0?"positive":"negative"}><small>预计差价</small><strong>{profit.toFixed(6)} {config.currency}</strong></div><div><small>利润率</small><strong>{margin.toFixed(2)}%</strong></div><div><small>成本加价率</small><strong>{markup.toFixed(2)}%</strong></div></div><div className="formula-box"><code>成本 = 输入Token ÷ 1,000,000 × 上游输入价 + 输出Token ÷ 1,000,000 × 上游输出价</code><code>收入 = 输入Token ÷ 1,000,000 × 用户输入价 + 输出Token ÷ 1,000,000 × 用户输出价</code><code>利润率 = 差价 ÷ 收入 × 100%</code></div></aside></div><div className="config-import"><div><h3>复制 / 粘贴价格配置</h3><p>以后把供应商价格发给我，我会返回这类 JSON；粘贴后点击导入即可自动填表。</p></div><textarea value={importText} onChange={e=>setImportText(e.target.value)} placeholder={'粘贴 {"schema":"aethergate.price.v1", ... }'}/><div className="inline-actions"><button type="button" onClick={()=>{const text=JSON.stringify(blankPrice(data.models[0]),null,2);setImportText(text);setToolNotice("空白模板已生成")}}>生成空白模板</button><button type="button" className="primary" onClick={importConfig}>导入并填充</button></div>{toolNotice&&<p className="tool-notice">{toolNotice}</p>}</div><div className="price-history standalone-history"><h3>价格历史</h3>{data.priceVersions.length===0?<p className="sub-empty">暂无价格版本</p>:data.priceVersions.map(price=>{const model=data.models.find(item=>item.id===price.providerModelId);return <div className="price-row" key={price.id}><div><strong>{model?.publicName||"未知模型"}</strong><small>{price.billingKind} · {price.currency}/{price.unit} · {new Date(price.effectiveAt).toLocaleString("zh-CN",{hour12:false})}</small><span>成本：{price.inputPrice??"—"} / {price.outputPrice??"—"}　售价：{price.userInputPrice??"—"} / {price.userOutputPrice??"—"}</span></div><div><b className={price.expiresAt?"status":"status healthy"}>● {price.expiresAt?"已失效":"生效中"}</b>{!price.expiresAt&&<button onClick={()=>action({action:"expire-price-version",id:price.id})}>终止版本</button>}</div></div>})}</div></article></div>
}

function SmartPricingPanelV2({data,action}:{data:Snapshot;action:ActionFn}){
  const [config,setConfig]=useState<PriceConfig>(()=>blankPrice(data.models[0]));
  const [sampleInput,setSampleInput]=useState("1000000");
  const [sampleOutput,setSampleOutput]=useState("1000000");
  const [importText,setImportText]=useState("");
  const [toolNotice,setToolNotice]=useState("");
  const [importError,setImportError]=useState("");
  const [importing,setImporting]=useState(false);
  const [showImport,setShowImport]=useState(false);

  useEffect(()=>{if(!config.providerModelId&&data.models[0])queueMicrotask(()=>setConfig(blankPrice(data.models[0])))},[config.providerModelId,data.models]);
  const num=(value:string)=>Number(value)||0;
  const cost=num(config.inputPrice)*num(sampleInput)/1000000+num(config.outputPrice)*num(sampleOutput)/1000000;
  const revenue=num(config.userInputPrice)*num(sampleInput)/1000000+num(config.userOutputPrice)*num(sampleOutput)/1000000;
  const profit=revenue-cost;
  const margin=revenue>0?profit/revenue*100:0;
  const markup=cost>0?profit/cost*100:0;
  const update=(key:keyof PriceConfig,value:string)=>setConfig(current=>({...current,[key]:value}));
  const copyConfig=async()=>{
    const text=JSON.stringify(config,null,2);
    setImportText(text);
    try{await navigator.clipboard.writeText(text);setToolNotice("当前配置已复制")}
    catch{setToolNotice("配置已生成，请在导入窗口中手动复制")}
  };
  const importConfig=()=>{
    setImportError("");
    setImporting(true);
    try{
      const list=decodePriceConfigs(importText);
      const parsed=list[0];
      if(!parsed||parsed.schema!=="aethergate.price.v1")throw new Error("配置版本不正确，需要 aethergate.price.v1");
      const importedModel=canonicalModelName(parsed.model);
      const matched=data.models.find(model=>model.id===parsed.providerModelId||canonicalModelName(model.upstreamModelId)===importedModel||canonicalModelName(model.publicName)===importedModel);
      if(!matched)throw new Error(`模型“${parsed.model||"未命名"}”尚未在模型供应商中配置，请先添加该模型再导入价格`);
      const normalized=Object.fromEntries(Object.entries(parsed).map(([key,value])=>[key,value==null?"":String(value)])) as Partial<PriceConfig>;
      setConfig({...blankPrice(matched),...normalized,providerModelId:matched.id,model:matched.upstreamModelId});
      const batchNote=list.length>1?`检测到 ${list.length} 条配置，已填充第 1 条；当前表单一次生效一个模型。`:"";
      const successText=`导入成功：${matched.publicName}${batchNote?`。${batchNote}`:""}`;
      setToolNotice(successText);
      setShowImport(false);
      window.setTimeout(()=>document.querySelector(".smart-price-form")?.scrollIntoView({behavior:"smooth",block:"center"}),50);
    }catch(error){
      setImportError(error instanceof Error&&error.message&&error.message!=="Unexpected end of JSON input"?error.message:"JSON 格式无法解析，请检查逗号、引号和括号是否完整");
    }finally{
      setImporting(false);
    }
  };

  return <div className="content compact-content">
    <article className="table-card policy-panel">
      <div className="panel-head"><div><small>SMART PRICE CONFIG</small><h3>价格、利润测算与一键配置</h3></div><span className="alert-total">标准格式：aethergate.price.v1</span></div>
      <div className="smart-price-layout">
        <form className="smart-price-form" onSubmit={e=>{e.preventDefault();action({action:"create-price-version",...config})}}>
          <div className="pricing-form-head"><h3>创建价格新版本</h3><button type="button" onClick={()=>{setToolNotice("");setImportError("");setShowImport(true)}}>导入配置</button></div>
          <label>提供商模型<select value={config.providerModelId} onChange={e=>{const model=data.models.find(item=>item.id===e.target.value);setConfig(current=>({...current,providerModelId:e.target.value,model:model?.upstreamModelId||""}))}}>{data.models.map(model=><option value={model.id} key={model.id}>{model.publicName} → {model.upstreamModelId}</option>)}</select></label>
          <div className="form-grid">
            <label>计费类型<select value={config.billingKind} onChange={e=>update("billingKind",e.target.value)}><option value="metered">按量</option><option value="subscription">套餐 / AFP</option></select></label>
            <label>币种<input value={config.currency} onChange={e=>update("currency",e.target.value)}/></label>
            <label>单位<input value={config.unit} onChange={e=>update("unit",e.target.value)}/></label>
            <label>上游输入成本<input type="number" step="0.000001" value={config.inputPrice} onChange={e=>update("inputPrice",e.target.value)}/></label>
            <label>上游输出成本<input type="number" step="0.000001" value={config.outputPrice} onChange={e=>update("outputPrice",e.target.value)}/></label>
            <label>缓存输入成本<input type="number" step="0.000001" value={config.cacheInputPrice} onChange={e=>update("cacheInputPrice",e.target.value)}/></label>
            <label>用户输入售价<input type="number" step="0.000001" value={config.userInputPrice} onChange={e=>update("userInputPrice",e.target.value)}/></label>
            <label>用户输出售价<input type="number" step="0.000001" value={config.userOutputPrice} onChange={e=>update("userOutputPrice",e.target.value)}/></label>
          </div>
          <label>价格来源备注<input value={config.sourceNote} onChange={e=>update("sourceNote",e.target.value)} placeholder="官方价格、上下文分段与核对日期"/></label>
          <div className="inline-actions"><button className="primary">创建并生效</button><button type="button" onClick={copyConfig}>复制当前配置</button></div>
          {toolNotice&&!showImport&&<p className="tool-notice">{toolNotice}</p>}
          <p className="safe-note">修改价格会创建新版本，旧版本自动失效，历史调用不会重算。</p>
        </form>
        <aside className="profit-panel">
          <div><span>利润测算</span><h3>差价 = 用户售价 − 上游成本</h3></div>
          <div className="sample-grid"><label>示例输入 Token<input type="number" value={sampleInput} onChange={e=>setSampleInput(e.target.value)}/></label><label>示例输出 Token<input type="number" value={sampleOutput} onChange={e=>setSampleOutput(e.target.value)}/></label></div>
          <div className="profit-metrics"><div><small>预计成本</small><strong>{cost.toFixed(6)} {config.currency}</strong></div><div><small>预计收入</small><strong>{revenue.toFixed(6)} {config.currency}</strong></div><div className={profit>=0?"positive":"negative"}><small>预计差价</small><strong>{profit.toFixed(6)} {config.currency}</strong></div><div><small>利润率</small><strong>{margin.toFixed(2)}%</strong></div><div><small>成本加价率</small><strong>{markup.toFixed(2)}%</strong></div></div>
          <div className="formula-box"><code>成本 = 输入Token ÷ 1,000,000 × 上游输入价 + 输出Token ÷ 1,000,000 × 上游输出价</code><code>收入 = 输入Token ÷ 1,000,000 × 用户输入价 + 输出Token ÷ 1,000,000 × 用户输出价</code><code>利润率 = 差价 ÷ 收入 × 100%</code></div>
        </aside>
      </div>
      <div className="price-history standalone-history"><h3>价格历史</h3>{data.priceVersions.length===0?<p className="sub-empty">暂无价格版本</p>:data.priceVersions.map(price=>{const model=data.models.find(item=>item.id===price.providerModelId);return <div className="price-row" key={price.id}><div><strong>{model?.publicName||"未知模型"}</strong><small>{price.billingKind} · {price.currency}/{price.unit} · {new Date(price.effectiveAt).toLocaleString("zh-CN",{hour12:false})}</small><span>成本：{price.inputPrice??"—"} / {price.outputPrice??"—"}　售价：{price.userInputPrice??"—"} / {price.userOutputPrice??"—"}</span></div><div><b className={price.expiresAt?"status":"status healthy"}>● {price.expiresAt?"已失效":"生效中"}</b>{!price.expiresAt&&<button onClick={()=>action({action:"expire-price-version",id:price.id})}>终止版本</button>}</div></div>})}</div>
    </article>
    {showImport&&<div className="modal-backdrop"><form className="modal price-import-modal" role="dialog" aria-modal="true" aria-labelledby="price-import-title" onSubmit={event=>{event.preventDefault();importConfig()}}><div className="modal-head"><div><small>PRICE CONFIG IMPORT</small><h2 id="price-import-title">导入价格配置</h2></div><button type="button" aria-label="关闭" onClick={()=>setShowImport(false)}>×</button></div><p className="import-help">粘贴 aethergate.price.v1 JSON。只有匹配到已配置的提供商模型后才会填充；成功后弹窗自动关闭。</p><textarea autoFocus value={importText} onChange={e=>{setImportText(e.target.value);setImportError("")}} placeholder={'粘贴 {"schema":"aethergate.price.v1", ... }'}/>{importError&&<p className="import-error" role="alert">⚠ {importError}</p>}<div className="modal-actions import-modal-actions"><button type="button" onClick={()=>{const text=JSON.stringify(blankPrice(data.models[0]),null,2);setImportText(text);setImportError("");setToolNotice("空白模板已生成")}}>生成空白模板</button><span className="modal-action-spacer"/><button type="button" onClick={()=>setShowImport(false)}>取消</button><button type="submit" className="primary" disabled={importing||!importText.trim()}>{importing?"正在导入…":"导入并填充"}</button></div></form></div>}
  </div>;
}

function PricingPanel({data,action}:{data:Snapshot;action:ActionFn}){return <div className="content compact-content"><article className="table-card policy-panel"><div className="panel-head"><div><small>PRICE VERSIONS</small><h3>模型价格与历史版本</h3></div></div><div className="policy-grid price-grid"><form onSubmit={e=>{e.preventDefault();action({action:"create-price-version",...formObject(e.currentTarget)})}}><h3>创建价格新版本</h3><label>提供商模型<select name="providerModelId">{data.models.map(model=><option value={model.id} key={model.id}>{model.publicName} → {model.upstreamModelId}</option>)}</select></label><div className="form-grid"><label>计费类型<select name="billingKind"><option value="metered">按量</option><option value="subscription">套餐 / AFP</option></select></label><label>币种<input name="currency" defaultValue="USD"/></label><label>单位<input name="unit" defaultValue="1M_tokens"/></label><label>上游输入价<input name="inputPrice" type="number" step="0.000001"/></label><label>上游输出价<input name="outputPrice" type="number" step="0.000001"/></label><label>缓存输入价<input name="cacheInputPrice" type="number" step="0.000001"/></label><label>用户输入价<input name="userInputPrice" type="number" step="0.000001"/></label><label>用户输出价<input name="userOutputPrice" type="number" step="0.000001"/></label></div><label>价格来源备注<input name="sourceNote" placeholder="例如：官方价格页，2026-08 核对"/></label><button className="primary">创建并生效</button><p className="safe-note">修改价格会创建新版本，旧版本自动失效，历史调用不会重算。</p></form><div className="price-history"><h3>价格历史</h3>{data.priceVersions.length===0?<p className="sub-empty">暂无价格版本</p>:data.priceVersions.map(price=>{const model=data.models.find(item=>item.id===price.providerModelId);return <div className="price-row" key={price.id}><div><strong>{model?.publicName||"未知模型"}</strong><small>{price.billingKind} · {price.currency}/{price.unit} · {new Date(price.effectiveAt).toLocaleString("zh-CN",{hour12:false})}</small><span>成本：{price.inputPrice??"—"} / {price.outputPrice??"—"}　结算：{price.userInputPrice??"—"} / {price.userOutputPrice??"—"}</span></div><div><b className={price.expiresAt?"status":"status healthy"}>● {price.expiresAt?"已失效":"生效中"}</b>{!price.expiresAt&&<button onClick={()=>action({action:"expire-price-version",id:price.id})}>终止版本</button>}</div></div>})}</div></div></article></div>}

function InvitePolicyEditor({data,action}:{data:Snapshot;action:ActionFn}){const pending=data.invitations.filter(invite=>invite.status==="pending");return <div className="content compact-content"><article className="table-card policy-panel"><div className="panel-head"><div><small>INVITE POLICY</small><h3>编辑未兑换邀请策略</h3></div></div><div className="invite-edit-list">{pending.length===0?<p className="sub-empty">没有可编辑的未兑换邀请</p>:pending.map(invite=><form key={invite.id} onSubmit={e=>{e.preventDefault();action({action:"update-invite",id:invite.id,...formObject(e.currentTarget)})}}><code>{invite.code}</code><div className="form-grid"><label>邮箱<input name="email" type="email" defaultValue={invite.email||""}/></label><label>备注<input name="note" defaultValue={invite.note||""}/></label><label>月请求<input name="monthlyRequestLimit" type="number" defaultValue={invite.monthlyRequestLimit||""}/></label><label>月 Token<input name="monthlyTokenLimit" type="number" defaultValue={invite.monthlyTokenLimit||""}/></label><label>RPM<input name="rpmLimit" type="number" defaultValue={invite.rpmLimit}/></label><label>并发<input name="concurrencyLimit" type="number" defaultValue={invite.concurrencyLimit}/></label></div><button className="primary">保存邀请策略</button></form>)}</div></article></div>}

function SettingsPage({data,action}:{data:Snapshot;action:ActionFn}){const settings=data.settings;return <div className="content"><div className="toolbar"><div><span className="eyebrow">SYSTEM SETTINGS</span><h2>全站设置</h2><p>全站速率、并发、正文大小、Token 与预算上限保存后立即参与网关校验。</p></div></div><article className="table-card settings-card"><form onSubmit={e=>{e.preventDefault();action({action:"update-system-settings",...formObject(e.currentTarget)})}}><div className="settings-section"><h3>流量与并发</h3><div className="form-grid"><label>全站 RPM<input name="global_rpm" type="number" defaultValue={settings.global_rpm||"1000"}/><small>一分钟内允许的总请求数</small></label><label>全站 TPM<input name="global_tpm" type="number" defaultValue={settings.global_tpm||"1000000"}/><small>一分钟内允许的总 Token</small></label><label>全站并发<input name="global_concurrency" type="number" defaultValue={settings.global_concurrency||"30"}/><small>所有成员共享</small></label></div></div><div className="settings-section"><h3>请求安全边界</h3><div className="form-grid"><label>最大正文（字节）<input name="max_body_bytes" type="number" defaultValue={settings.max_body_bytes||"1048576"}/></label><label>最大输入 Token<input name="max_input_tokens" type="number" defaultValue={settings.max_input_tokens||"200000"}/></label><label>最大输出 Token<input name="max_output_tokens" type="number" defaultValue={settings.max_output_tokens||"32768"}/></label></div></div><div className="settings-section"><h3>预算</h3><div className="form-grid"><label>站点月度预算<input name="monthly_budget" type="number" step="0.01" defaultValue={settings.monthly_budget||"1000"}/><small>按调用账本成本金额统计</small></label></div></div><div className="inline-actions"><button className="primary">保存系统设置</button><span className={data.gatewayEnabled?"status healthy":"status"}>● 网关{data.gatewayEnabled?"运行中":"已停止"}</span></div></form></article></div>}

function Alerts({events,action}:{events:HealthEvent[];action:ActionFn}) {
  const recovered=(event:HealthEvent)=>event.eventType.includes("recovered")||event.level==="info";
  const critical=events.filter(event=>event.level==="error"&&!recovered(event)).length;
  const warnings=events.filter(event=>event.level==="warning"&&!recovered(event)).length;
  const recoveredCount=events.filter(recovered).length;
  const pending=events.filter(event=>!event.readAt).length;
  const metrics=[["严重",critical],["警告",warnings],["待处理",pending],["已恢复",recoveredCount]] as const;
  return <div className="content"><div className="toolbar"><div><span className="eyebrow">ALERT CENTER</span><h2>告警中心</h2><p>密钥、预算、路由、并发和结算异常集中处理。</p></div>{pending>0&&<button className="primary" onClick={()=>action({action:"read-all-health-events"})}>✓ 清除全部未读</button>}</div><section className="metric-row">{metrics.map(([label,value])=><div key={label}><small>{label}</small><strong>{value}</strong><span>实时统计</span></div>)}</section><article className="table-card alerts-card"><div className="panel-head"><div><small>HEALTH EVENTS</small><h3>告警与恢复记录</h3></div><span className="alert-total">{pending} 条未读 · 共 {events.length} 条</span></div>{events.length===0?<div className="all-clear"><span>✓</span><strong>暂无告警</strong><small>系统状态正常</small></div>:<div className="alerts-list">{events.map(event=>{const isRecovered=recovered(event);const tone=isRecovered?"recovered":event.level==="error"?"critical":"warning";return <div className={`alert-row ${event.readAt?"read":"unread"}`} key={event.id}><span className={`alert-symbol ${tone}`}>{isRecovered?"✓":event.level==="error"?"!":"△"}</span><div className="alert-copy"><div><strong>{event.summary}</strong><span className={`alert-state ${tone}`}>{isRecovered?"已恢复":event.level==="error"?"严重":"警告"}</span></div><small>{new Date(event.createdAt).toLocaleString("zh-CN",{hour12:false})}{event.readAt?" · 已读":" · 未读"}</small></div>{!event.readAt&&<button className="read-button" onClick={()=>action({action:"read-health-event",id:event.id})}>标为已读</button>}</div>})}</div>}</article></div>;
}

function ModulePage({ active, data, onAddMember }: { active:string; data:Snapshot; onAddMember:()=>void }) {
  const config: Record<string, [string,string,string[]]> = {
    models:["公共模型与价格","公共名称与上游模型解耦；价格修改会产生不可变版本。",["公共模型","上游路由","能力参数","价格版本"]], members:["成员与个人 API Key","权限、额度、速率和并发可逐层收紧。",["正常成员","个人 Key","本月用量","并发占用"]], invites:["邀请管理","一次性邀请绑定默认模型权限与额度策略。",["未兑换","已兑换","已过期","已撤销"]], limits:["额度与流量控制","全站到个人 Key 的限制叠加后取最严格值。",["全站并发","RPM","TPM","月度预算"]], calls:["调用记录与账本","只记录用量、状态、路由和耗时，不保存提示词或回答。",["今日请求","成功率","输入 Token","输出 Token"]], alerts:["告警中心","密钥、预算、路由、并发和结算异常集中处理。",["严重","警告","待处理","已恢复"]], audit:["审计日志","敏感操作保留变更摘要，不记录任何密钥明文。",["今日操作","密钥变更","权限变更","失败操作"]], settings:["系统设置","网关开关、安全策略与全站默认限制。",["安全策略","网关设置","日志策略","密钥版本"]],
  };
  const [title, desc, metrics] = config[active] || config.models;
  return <div className="content"><div className="toolbar"><div><span className="eyebrow">CONTROL MODULE</span><h2>{title}</h2><p>{desc}</p></div>{active === "members" && <button className="primary" onClick={onAddMember}>＋ 添加成员</button>}</div><section className="metric-row">{metrics.map((m,i)=><div key={m}><small>{m}</small><strong>{active === "members" && i===0 ? data.stats.members : active === "calls" && i===0 ? data.stats.callsToday : "0"}</strong><span>实时统计</span></div>)}</section><article className="panel module-panel"><div className="module-graphic"><span>{navigation.find(n=>n[0]===active)?.[2]}</span></div><h3>{title}已就绪</h3><p>数据结构、权限边界和审计字段已经建立。新增记录后，这里将显示完整的列表、穿透详情和状态操作。</p><div className="feature-tags">{metrics.map(m=><span key={m}>✓ {m}</span>)}</div></article></div>;
}

function Empty({ text, action, onClick }: { text:string; action:string; onClick:()=>void }) { return <div className="empty"><span>＋</span><strong>{text}</strong><button onClick={onClick}>{action}</button></div> }
